package ycscite;

import ycscite.io.*;
import ycscite.model.*;
import ycscite.ui.GraphCanvas;
import javax.swing.SwingUtilities;
import java.awt.*;
import java.awt.event.MouseEvent;
import java.awt.geom.Point2D;
import java.awt.image.BufferedImage;
import java.nio.file.*;
import java.util.*;
import java.util.List;

/** Saved visual state must reproduce hand edits without modifying the scientific network. */
public final class PresentationTests {
 private static Map<String,Object> cloneMap(Map<String,Object> value){return MiniJson.obj(MiniJson.parse(MiniJson.write(value)));}
 private static int[] pixels(BufferedImage image){return image.getRGB(0,0,image.getWidth(),image.getHeight(),null,0,image.getWidth());}
 private static BufferedImage paint(GraphCanvas canvas){var image=new BufferedImage(canvas.getWidth(),canvas.getHeight(),BufferedImage.TYPE_INT_RGB);var graphics=image.createGraphics();canvas.paint(graphics);graphics.dispose();return image;}
 public static void run()throws Exception{
  var graph=new Network("saved visual test");for(int i=0;i<4;i++){var n=graph.node("n"+i,"节点"+i,"keyword");n.weight=4-i;n.cluster=i<2?1:2;n.addYear(2020+i%2);}graph.linkWeighted(graph.nodes.get("n0"),graph.nodes.get("n1"),3);graph.linkWeighted(graph.nodes.get("n1"),graph.nodes.get("n2"),1);graph.linkWeighted(graph.nodes.get("n2"),graph.nodes.get("n3"),2);graph.minYear=2020;graph.maxYear=2021;
  var node=graph.nodes.get("n0");String identity=ProjectStore.networkFingerprint(graph);var live=new GraphCanvas();
  SwingUtilities.invokeAndWait(()->{live.setSize(920,620);live.show(graph,GraphCanvas.Mode.MERGED,"保存视图");live.setNodePosition("n0",260,170);live.setNodeHidden("n3",true);live.setTheme(GraphCanvas.Theme.SEPIA);live.setNodeShape(GraphCanvas.NodeShape.DIAMOND);live.setNodeScale(1.7);live.setLabelFontSize(17);live.setLabelBudget(4);live.setLinkTransparency(.7f);live.setCurvedLines(true);live.setLabelAngle(30);live.setShowCitationCount(true);live.setHighlightList(Set.of("节点0"));live.setSelectedNode(node);live.focus("n0");});
  final var states=new java.util.concurrent.atomic.AtomicReference<Map<String,Object>>();final BufferedImage[] before={null};SwingUtilities.invokeAndWait(()->{states.set(live.captureState());before[0]=paint(live);});var state=states.get();
  TestAll.check("presentation.graph_unchanged",identity.equals(ProjectStore.networkFingerprint(graph)),"manual layout and filtering must not rewrite counts, clusters or metrics");
  var restored=new GraphCanvas();SwingUtilities.invokeAndWait(()->{restored.setSize(920,620);restored.show(graph,GraphCanvas.Mode.MERGED,"ignored",state);restored.setClusterLabels(Map.of());});final BufferedImage[] after={null};SwingUtilities.invokeAndWait(()->after[0]=paint(restored));
  TestAll.check("presentation.visible_pixels",Arrays.equals(pixels(before[0]),pixels(after[0])),"the same-size UI restores its manual layout, camera and style exactly");
  TestAll.check("presentation.positions_and_filter",restored.positionOf(node).equals(new Point2D.Double(260,170))&&restored.visibleNodes().stream().noneMatch(n->n.id.equals("n3")),"manual positions and hidden nodes survive");
  var resized=new GraphCanvas();SwingUtilities.invokeAndWait(()->{resized.setSize(1100,700);resized.show(graph,GraphCanvas.Mode.MERGED,"resize",state);});final var resizedState=new java.util.concurrent.atomic.AtomicReference<Map<String,Object>>();SwingUtilities.invokeAndWait(()->resizedState.set(resized.captureState()));var oldCamera=MiniJson.obj(state.get("camera"));var newCamera=MiniJson.obj(resizedState.get().get("camera"));TestAll.check("presentation.camera_resize",Math.abs(MiniJson.num(oldCamera.get("scale"))-MiniJson.num(newCamera.get("scale")))<1e-12&&Math.abs(MiniJson.num(oldCamera.get("center_x"))-MiniJson.num(newCamera.get("center_x")))<1e-12&&Math.abs(MiniJson.num(oldCamera.get("center_y"))-MiniJson.num(newCamera.get("center_y")))<1e-12,"camera center and relative zoom survive a different window size");
  resized.showAllNodes();TestAll.check("presentation.show_all_without_analysis",resized.visibleNodes().size()==graph.nodes.size()&&identity.equals(ProjectStore.networkFingerprint(graph)),"restoring hidden nodes is a view action, not a scientific recomputation");resized.fitToWindow();var fitCamera=MiniJson.obj(resized.captureState().get("camera"));TestAll.check("presentation.fit_recovers_camera",Math.abs(MiniJson.num(fitCamera.get("scale"))-1)<1e-12,"fit-to-window recovers from a saved zoom/pan");
  var originalExport=live.renderImage(1600,1000);var restoredExport=restored.renderImage(1600,1000);TestAll.check("presentation.export_pixels",Arrays.equals(pixels(originalExport),pixels(restoredExport)),"saved visual exports are reproducible");originalExport.flush();restoredExport.flush();
  var snapshot=MiniJson.write(restored.captureState());var invalid=cloneMap(state);MiniJson.obj(invalid.get("positions")).put("unknown-node",List.of(1,2));boolean rejected=false;try{restored.restoreState(invalid);}catch(IllegalArgumentException error){rejected=true;}TestAll.check("presentation.invalid_atomic",rejected&&snapshot.equals(MiniJson.write(restored.captureState())),"invalid state must not partially change a canvas");
  invalid=cloneMap(state);MiniJson.obj(invalid.get("camera")).put("scale",Double.NaN);boolean finite=false;try{restored.restoreState(invalid);}catch(IllegalArgumentException error){finite=true;}TestAll.check("presentation.nonfinite_rejected",finite,"camera data must be finite");
  var wrong=graph.deepCopy();wrong.nodes.get("n0").weight++;boolean foreign=false;try{ViewState.checked(state,wrong,"MERGED");}catch(IllegalArgumentException error){foreign=true;}TestAll.check("presentation.graph_identity",foreign,"layout identity must match the analyzed network including its metrics");
  var timeline=new GraphCanvas();timeline.show(graph,GraphCanvas.Mode.TIMELINE,"time");var initial=timeline.positionOf(node);timeline.setNodePosition(node.id,initial.x+400,initial.y+15);TestAll.check("presentation.year_axis_locked",timeline.positionOf(node).x==initial.x,"manual moves cannot silently change the encoded first-appearance year");

  Path root=Files.createTempDirectory("ycscite-presentation-");var project=new Project();project.name="手工布局";var record=new ycscite.model.Record();record.title="示例";record.year=2020;project.add(record);var result=new ycscite.analysis.Pipeline.Result();result.network=graph;result.clusterLabels=Map.of();result.clusterStats=Map.of();result.modularity=.42;
  var presentation=Map.<String,Object>of("schema_version",1,"language","zh","active_view","MERGED","canvases",Map.of("MERGED",state));Path file=root.resolve("edited.csl-proj");ProjectStore.save(file,project,result,new ycscite.analysis.Pipeline.Options(),false,presentation);var bundle=ProjectStore.load(file);
  TestAll.check("presentation.project_roundtrip",MiniJson.write(bundle.presentation).equals(MiniJson.write(ViewState.editor(presentation,graph))),"a portable project contains validated visual state");
  Path out=root.resolve("headless");var response=Headless.execute(Map.of("method","project","params",Map.of("action","export","path",file.toString(),"output",out.toString(),"formats",List.of("png","svg","pdf","tsv"),"width",1600,"height",1000)));TestAll.check("presentation.headless_export",Boolean.TRUE.equals(response.get("ok"))&&Files.exists(out.resolve("project-export.json")),response.toString());
  var expected=ProjectExports.canvas(bundle,GraphCanvas.Mode.MERGED).renderImage(1600,1000);try(var pair=Branding.images(expected)){var actual=javax.imageio.ImageIO.read(out.resolve("network.png").toFile());TestAll.check("presentation.headless_matches_editor",Arrays.equals(pixels(pair.plain()),pixels(actual)),"headless exports the stored coordinates/style rather than computing a default layout");actual.flush();}expected.flush();
  String svg=Files.readString(out.resolve("network.svg"));TestAll.check("presentation.svg_visibility",!svg.contains("节点3")&&svg.contains("节点0"),"vector export respects saved filters");
  var inspected=Headless.execute(Map.of("method","project","params",Map.of("action","inspect","path",file.toString())));var info=MiniJson.obj(inspected.get("result"));TestAll.check("presentation.headless_inspect",Boolean.TRUE.equals(inspected.get("ok"))&&Boolean.TRUE.equals(info.get("has_saved_views"))&&"MERGED".equals(info.get("active_view"))&&graph.nodes.size()==MiniJson.num(info.get("nodes")),"project inspection reports available layouts without analysis");
  Path invalidOut=root.resolve("invalid");var bad=Headless.execute(Map.of("method","project","params",Map.of("action","export","path",file.toString(),"output",invalidOut.toString(),"formats",List.of("invalid"))));TestAll.check("presentation.bad_export_no_output",Boolean.FALSE.equals(bad.get("ok"))&&!Files.exists(invalidOut),"export validation precedes output writes");
  byte[] originalProject=Files.readAllBytes(file);boolean protectedFile=false;try{ProjectStore.save(file,project,result,new ycscite.analysis.Pipeline.Options(),false,Map.of("schema_version",2));}catch(IllegalArgumentException error){protectedFile=true;}TestAll.check("presentation.failed_save_preserves_file",protectedFile&&Arrays.equals(originalProject,Files.readAllBytes(file)),"a rejected visual state must not replace an existing project");
  Path defaultsFile=root.resolve("report-defaults.csl-proj");var defaults=new Settings(Map.of("node_scale",1.8,"label_scale",1.3,"label_budget",19,"link_opacity",.4));ProjectStore.saveFromReport(defaultsFile,project,result,new ycscite.analysis.Pipeline.Options(),defaults);var withDefaults=ProjectStore.load(defaultsFile);var display=MiniJson.obj(ProjectExports.canvas(withDefaults,GraphCanvas.Mode.MERGED).captureState().get("display"));TestAll.check("presentation.report_style_defaults",MiniJson.num(display.get("node_scale"))==1.8&&Math.abs(MiniJson.num(display.get("font_size"))-15.6)<1e-5&&MiniJson.num(display.get("label_budget"))==19,"report projects retain user display parameters before a manual layout exists");
  Path legacy=root.resolve("legacy.csl-proj");ProjectStore.save(legacy,project,result,new ycscite.analysis.Pipeline.Options());var old=ProjectStore.load(legacy);TestAll.check("presentation.legacy_compatible",old.presentation.isEmpty()&&ProjectStore.networkFingerprint(old.result.network).equals(identity),"older projects remain usable without inventing a saved manual layout");
  Map<String,Object> tampered=MiniJson.obj(MiniJson.parse(Files.readString(file)));MiniJson.obj(MiniJson.obj(tampered.get("presentation")).get("canvases")).put("MERGED",invalid);Path damaged=root.resolve("damaged.csl-proj");Files.writeString(damaged,MiniJson.write(tampered));var malformed=Headless.execute(Map.of("method","project","params",Map.of("action","inspect","path",damaged.toString())));TestAll.check("presentation.malformed_project_rejected",Boolean.FALSE.equals(malformed.get("ok")),"malformed view state is not silently treated as a fresh layout");

  for(var mode:GraphCanvas.Mode.values()){
   var firstCanvas=new GraphCanvas();firstCanvas.show(graph,mode,"per-view");firstCanvas.setTheme(GraphCanvas.Theme.LIGHT);firstCanvas.setLabelFontSize(14.5f);firstCanvas.setLabelBudget(4);firstCanvas.setNodeHidden("n3",true);var savedView=cloneMap(firstCanvas.captureState());
   var secondCanvas=new GraphCanvas();secondCanvas.show(graph.deepCopy(),mode,"ignored",savedView);secondCanvas.setClusterLabels(Map.of());var firstImage=firstCanvas.renderImage(1000,700);var secondImage=secondCanvas.renderImage(1000,700);
   TestAll.check("presentation.mode_"+mode.name().toLowerCase(java.util.Locale.ROOT),Arrays.equals(pixels(firstImage),pixels(secondImage)),"each available view restores its own coordinates/style/filter after a JSON roundtrip");firstImage.flush();secondImage.flush();
  }
  var rawGraph=new Network("raw labels");var rawNode=rawGraph.node("keyword","关键词","keyword");rawNode.weight=10;rawNode.addYear(2020);rawGraph.minYear=rawGraph.maxYear=2020;var rawCanvas=new GraphCanvas();rawCanvas.show(rawGraph,GraphCanvas.Mode.MERGED,"raw label");var languageBefore=ycscite.ui.Strings.getLang();BufferedImage firstLanguage,secondLanguage;try{ycscite.ui.Strings.setLang(ycscite.ui.Strings.Lang.EN);try(var language=I18n.language("zh")){firstLanguage=rawCanvas.renderImage(800,500);}try(var language=I18n.language("en")){secondLanguage=rawCanvas.renderImage(800,500);}}finally{ycscite.ui.Strings.setLang(languageBefore);}TestAll.check("presentation.bibliographic_labels_preserved",Arrays.equals(pixels(firstLanguage),pixels(secondLanguage)),"original node labels that resemble interface terms must not be translated");firstLanguage.flush();secondLanguage.flush();
  var dragged=new GraphCanvas();SwingUtilities.invokeAndWait(()->{dragged.setSize(1150,700);dragged.show(graph,GraphCanvas.Mode.MERGED,"drag");dragged.setNodePosition("n0",200,180);dragged.dispatchEvent(new MouseEvent(dragged,MouseEvent.MOUSE_PRESSED,1,MouseEvent.BUTTON1_DOWN_MASK,200,180,1,false,MouseEvent.BUTTON1));dragged.dispatchEvent(new MouseEvent(dragged,MouseEvent.MOUSE_DRAGGED,2,MouseEvent.BUTTON1_DOWN_MASK,245,215,0,false,MouseEvent.NOBUTTON));dragged.dispatchEvent(new MouseEvent(dragged,MouseEvent.MOUSE_RELEASED,3,0,245,215,1,false,MouseEvent.BUTTON1));});TestAll.check("presentation.real_drag_moves_node",dragged.positionOf(node).equals(new Point2D.Double(245,215)),"actual mouse events move a node rather than pan the whole graph");
  SwingUtilities.invokeAndWait(()->{dragged.setEnabled(false);dragged.dispatchEvent(new MouseEvent(dragged,MouseEvent.MOUSE_PRESSED,4,MouseEvent.BUTTON1_DOWN_MASK,245,215,1,false,MouseEvent.BUTTON1));dragged.dispatchEvent(new MouseEvent(dragged,MouseEvent.MOUSE_DRAGGED,5,MouseEvent.BUTTON1_DOWN_MASK,280,250,0,false,MouseEvent.NOBUTTON));dragged.dispatchEvent(new MouseEvent(dragged,MouseEvent.MOUSE_RELEASED,6,0,280,250,1,false,MouseEvent.BUTTON1));});TestAll.check("presentation.busy_drag_ignored",dragged.positionOf(node).equals(new Point2D.Double(245,215)),"node edits are disabled while a layout is being prepared");
 }
}
